-- OpenInbox schema v1.
-- Ids are time-sortable integers generated by the Worker (src/worker/lib/ids.ts), so a D1 batch
-- can insert rows that reference each other. Timestamps are Unix epoch milliseconds.

CREATE TABLE settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  updated_at INTEGER NOT NULL
);

-- Accounts and auth ---------------------------------------------------------------------------

CREATE TABLE users (
  id INTEGER PRIMARY KEY,
  email TEXT NOT NULL UNIQUE COLLATE NOCASE,
  name TEXT NOT NULL DEFAULT '',
  password_hash TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('owner', 'admin', 'member')),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  must_change_password INTEGER NOT NULL DEFAULT 0,
  totp_secret TEXT,               -- encrypted
  totp_enabled INTEGER NOT NULL DEFAULT 0,
  recovery_codes TEXT,            -- JSON array of SHA-256 hashes of unused codes
  preferences TEXT NOT NULL DEFAULT '{}',
  created_at INTEGER NOT NULL,
  last_login_at INTEGER
);

CREATE TABLE sessions (
  id TEXT PRIMARY KEY,            -- SHA-256 hex of the cookie token; the token itself is never stored
  user_id INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  csrf TEXT NOT NULL,
  mfa_pending INTEGER NOT NULL DEFAULT 0,
  ip TEXT,
  user_agent TEXT,
  created_at INTEGER NOT NULL,
  last_seen_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL
);
CREATE INDEX sessions_user ON sessions (user_id);
CREATE INDEX sessions_expiry ON sessions (expires_at);

CREATE TABLE auth_attempts (
  key TEXT PRIMARY KEY,           -- e.g. 'login:ip:203.0.113.5' or 'login:user:a@example.com'
  count INTEGER NOT NULL,
  window_start INTEGER NOT NULL
);

-- Domains, mailboxes, addresses -----------------------------------------------------------------

CREATE TABLE domains (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL UNIQUE COLLATE NOCASE,
  zone_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'error', 'disabled')),
  catch_all_mailbox_id INTEGER REFERENCES mailboxes (id) ON DELETE SET NULL,
  provider_id INTEGER REFERENCES providers (id) ON DELETE SET NULL,  -- sending override; NULL = default
  setup_state TEXT NOT NULL DEFAULT '{}',   -- per-step state, so setup is idempotent and resumable
  health TEXT NOT NULL DEFAULT '{}',
  health_checked_at INTEGER,
  app_hostname TEXT,                        -- mail.<domain>, when attached as the app's custom domain
  created_at INTEGER NOT NULL
);

CREATE TABLE mailboxes (
  id INTEGER PRIMARY KEY,
  domain_id INTEGER NOT NULL REFERENCES domains (id),
  address TEXT NOT NULL UNIQUE COLLATE NOCASE,
  display_name TEXT NOT NULL DEFAULT '',
  kind TEXT NOT NULL DEFAULT 'personal' CHECK (kind IN ('personal', 'shared')),
  signature TEXT NOT NULL DEFAULT '',       -- HTML
  auto_reply TEXT,                          -- JSON
  forward_to TEXT NOT NULL DEFAULT '[]',    -- JSON array of Email Routing destination addresses
  state INTEGER NOT NULL DEFAULT 0,         -- bumped on every change; clients poll it
  created_at INTEGER NOT NULL
);

CREATE TABLE addresses (
  id INTEGER PRIMARY KEY,
  address TEXT NOT NULL UNIQUE COLLATE NOCASE,
  domain_id INTEGER NOT NULL REFERENCES domains (id) ON DELETE CASCADE,
  mailbox_id INTEGER NOT NULL REFERENCES mailboxes (id) ON DELETE CASCADE,
  is_primary INTEGER NOT NULL DEFAULT 0,
  display_name TEXT,
  created_at INTEGER NOT NULL
);
CREATE INDEX addresses_mailbox ON addresses (mailbox_id);
CREATE INDEX addresses_domain ON addresses (domain_id);

CREATE TABLE mailbox_members (
  mailbox_id INTEGER NOT NULL REFERENCES mailboxes (id) ON DELETE CASCADE,
  user_id INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  can_send INTEGER NOT NULL DEFAULT 1,
  PRIMARY KEY (mailbox_id, user_id)
);
CREATE INDEX mailbox_members_user ON mailbox_members (user_id);

-- Sending providers ------------------------------------------------------------------------------

CREATE TABLE providers (
  id INTEGER PRIMARY KEY,
  type TEXT NOT NULL CHECK (type IN ('resend', 'brevo', 'mailjet', 'smtp')),
  name TEXT NOT NULL,
  config TEXT NOT NULL,           -- encrypted JSON credentials
  status TEXT NOT NULL DEFAULT 'unknown' CHECK (status IN ('unknown', 'connected', 'error')),
  last_error TEXT,
  checked_at INTEGER,
  priority INTEGER NOT NULL DEFAULT 0,      -- fallback order, lowest first
  is_default INTEGER NOT NULL DEFAULT 0,
  daily_limit INTEGER,
  monthly_limit INTEGER,
  webhook_secret TEXT,            -- encrypted
  webhook_id TEXT,
  created_at INTEGER NOT NULL
);

CREATE TABLE provider_domains (
  provider_id INTEGER NOT NULL REFERENCES providers (id) ON DELETE CASCADE,
  domain_id INTEGER NOT NULL REFERENCES domains (id) ON DELETE CASCADE,
  external_id TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'verified', 'failed')),
  records TEXT NOT NULL DEFAULT '[]',
  last_error TEXT,
  checked_at INTEGER,
  PRIMARY KEY (provider_id, domain_id)
);
CREATE INDEX provider_domains_domain ON provider_domains (domain_id);

CREATE TABLE quota_usage (
  provider_id INTEGER NOT NULL REFERENCES providers (id) ON DELETE CASCADE,
  day TEXT NOT NULL,              -- UTC YYYY-MM-DD
  count INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (provider_id, day)
);

CREATE TABLE suppressions (
  address TEXT PRIMARY KEY COLLATE NOCASE,
  reason TEXT NOT NULL CHECK (reason IN ('bounce', 'complaint', 'manual')),
  detail TEXT,
  created_at INTEGER NOT NULL
);

-- Mail ---------------------------------------------------------------------------------------------

CREATE TABLE threads (
  id INTEGER PRIMARY KEY,
  mailbox_id INTEGER NOT NULL REFERENCES mailboxes (id) ON DELETE CASCADE,
  folder TEXT NOT NULL DEFAULT 'inbox' CHECK (folder IN ('inbox', 'archive', 'spam', 'trash')),
  subject TEXT NOT NULL DEFAULT '',
  subject_norm TEXT NOT NULL DEFAULT '',
  snippet TEXT NOT NULL DEFAULT '',
  participants TEXT NOT NULL DEFAULT '[]',  -- JSON [{name, address}], most recent first
  message_count INTEGER NOT NULL DEFAULT 0, -- received and sent messages, not drafts
  unread_count INTEGER NOT NULL DEFAULT 0,
  draft_count INTEGER NOT NULL DEFAULT 0,
  has_attachments INTEGER NOT NULL DEFAULT 0,
  starred INTEGER NOT NULL DEFAULT 0,
  last_message_at INTEGER NOT NULL,
  last_inbound_at INTEGER,
  last_sent_at INTEGER,
  snoozed_until INTEGER,
  assigned_to INTEGER REFERENCES users (id) ON DELETE SET NULL,
  updated_at INTEGER NOT NULL
);
CREATE INDEX threads_folder ON threads (mailbox_id, folder, last_message_at DESC);
CREATE INDEX threads_sent ON threads (mailbox_id, last_sent_at DESC) WHERE last_sent_at IS NOT NULL;
CREATE INDEX threads_starred ON threads (mailbox_id, last_message_at DESC) WHERE starred = 1;
CREATE INDEX threads_drafts ON threads (mailbox_id, last_message_at DESC) WHERE draft_count > 0;
CREATE INDEX threads_unread ON threads (mailbox_id, folder) WHERE unread_count > 0;
CREATE INDEX threads_subject ON threads (mailbox_id, subject_norm, last_message_at DESC);
CREATE INDEX threads_snoozed ON threads (snoozed_until) WHERE snoozed_until IS NOT NULL;

CREATE TABLE messages (
  id INTEGER PRIMARY KEY,
  thread_id INTEGER NOT NULL REFERENCES threads (id) ON DELETE CASCADE,
  mailbox_id INTEGER NOT NULL REFERENCES mailboxes (id) ON DELETE CASCADE,
  direction TEXT NOT NULL CHECK (direction IN ('in', 'out')),
  status TEXT NOT NULL CHECK (status IN (
    'received', 'unparsed', 'draft', 'scheduled', 'sending', 'sent', 'failed', 'delivered', 'bounced', 'complained'
  )),
  message_id TEXT,                -- Message-ID without angle brackets (our own for outbound)
  in_reply_to TEXT,
  refs TEXT,                      -- References, space separated, without angle brackets
  from_addr TEXT NOT NULL DEFAULT '',
  from_name TEXT NOT NULL DEFAULT '',
  to_addrs TEXT NOT NULL DEFAULT '[]',      -- JSON [{name, address}]
  cc_addrs TEXT NOT NULL DEFAULT '[]',
  bcc_addrs TEXT NOT NULL DEFAULT '[]',
  reply_to TEXT,
  delivered_to TEXT,              -- envelope recipient of inbound mail
  subject TEXT NOT NULL DEFAULT '',
  snippet TEXT NOT NULL DEFAULT '',
  sent_at INTEGER NOT NULL,       -- Date header for inbound, send time for outbound
  is_read INTEGER NOT NULL DEFAULT 0,
  has_attachments INTEGER NOT NULL DEFAULT 0,
  size INTEGER NOT NULL DEFAULT 0,
  raw_key TEXT,                   -- blob store key, when the raw .eml is kept
  raw_store TEXT CHECK (raw_store IN ('d1', 'r2')),
  truncated INTEGER NOT NULL DEFAULT 0,     -- body clipped to fit D1's row limit
  spf TEXT,
  dkim TEXT,
  dmarc TEXT,
  spam_reason TEXT,
  list_unsubscribe TEXT,          -- JSON {url, mailto, oneClick}
  provider_id INTEGER REFERENCES providers (id) ON DELETE SET NULL,
  provider_message_id TEXT,
  send_at INTEGER,                -- scheduled send time
  attempts INTEGER NOT NULL DEFAULT 0,
  error TEXT,
  sent_by INTEGER REFERENCES users (id) ON DELETE SET NULL,
  created_at INTEGER NOT NULL
);
CREATE INDEX messages_thread ON messages (thread_id, sent_at);
CREATE INDEX messages_message_id ON messages (mailbox_id, message_id);
CREATE UNIQUE INDEX messages_dedupe ON messages (mailbox_id, message_id) WHERE direction = 'in' AND message_id IS NOT NULL;
CREATE INDEX messages_queue ON messages (status, send_at) WHERE status IN ('unparsed', 'scheduled', 'sending', 'failed');
CREATE INDEX messages_provider ON messages (provider_message_id) WHERE provider_message_id IS NOT NULL;

-- Bodies live apart from messages so lists never touch them. This table is also the external
-- content of the FTS5 index; triggers keep the index in sync (Phase 0 verified this on D1).
CREATE TABLE message_bodies (
  message_id INTEGER PRIMARY KEY REFERENCES messages (id) ON DELETE CASCADE,
  subject TEXT NOT NULL DEFAULT '',
  from_text TEXT NOT NULL DEFAULT '',
  to_text TEXT NOT NULL DEFAULT '',
  text TEXT NOT NULL DEFAULT '',
  html TEXT,
  headers TEXT NOT NULL DEFAULT '[]'        -- JSON [[name, value], ...], clipped
);

CREATE VIRTUAL TABLE messages_fts USING fts5 (
  subject, from_text, to_text, text,
  content = 'message_bodies', content_rowid = 'message_id',
  tokenize = 'unicode61 remove_diacritics 2'
);

CREATE TRIGGER message_bodies_ai AFTER INSERT ON message_bodies BEGIN
  INSERT INTO messages_fts (rowid, subject, from_text, to_text, text)
  VALUES (new.message_id, new.subject, new.from_text, new.to_text, new.text);
END;

CREATE TRIGGER message_bodies_ad AFTER DELETE ON message_bodies BEGIN
  INSERT INTO messages_fts (messages_fts, rowid, subject, from_text, to_text, text)
  VALUES ('delete', old.message_id, old.subject, old.from_text, old.to_text, old.text);
END;

CREATE TRIGGER message_bodies_au AFTER UPDATE ON message_bodies BEGIN
  INSERT INTO messages_fts (messages_fts, rowid, subject, from_text, to_text, text)
  VALUES ('delete', old.message_id, old.subject, old.from_text, old.to_text, old.text);
  INSERT INTO messages_fts (rowid, subject, from_text, to_text, text)
  VALUES (new.message_id, new.subject, new.from_text, new.to_text, new.text);
END;

CREATE TABLE attachments (
  id INTEGER PRIMARY KEY,
  message_id INTEGER NOT NULL REFERENCES messages (id) ON DELETE CASCADE,
  filename TEXT NOT NULL DEFAULT '',
  content_type TEXT NOT NULL DEFAULT 'application/octet-stream',
  size INTEGER NOT NULL DEFAULT 0,
  content_id TEXT,
  inline INTEGER NOT NULL DEFAULT 0,
  encoding TEXT,
  byte_offset INTEGER,            -- range of the encoded body inside the raw .eml
  byte_length INTEGER,
  stored INTEGER NOT NULL DEFAULT 0,        -- 1 when it can be downloaded (raw .eml or upload kept)
  upload_key TEXT                 -- R2 key of a compose upload
);
CREATE INDEX attachments_message ON attachments (message_id);

-- Raw .eml in text-only mode, as latin1 TEXT (byte-exact). Only messages up to 950 KB.
CREATE TABLE raw_messages (
  key TEXT PRIMARY KEY,
  data TEXT NOT NULL
);

CREATE TABLE labels (
  id INTEGER PRIMARY KEY,
  mailbox_id INTEGER NOT NULL REFERENCES mailboxes (id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  color TEXT NOT NULL DEFAULT 'slate',
  created_at INTEGER NOT NULL,
  UNIQUE (mailbox_id, name)
);

CREATE TABLE thread_labels (
  thread_id INTEGER NOT NULL REFERENCES threads (id) ON DELETE CASCADE,
  label_id INTEGER NOT NULL REFERENCES labels (id) ON DELETE CASCADE,
  PRIMARY KEY (thread_id, label_id)
);
CREATE INDEX thread_labels_label ON thread_labels (label_id);

CREATE TABLE thread_notes (
  id INTEGER PRIMARY KEY,
  thread_id INTEGER NOT NULL REFERENCES threads (id) ON DELETE CASCADE,
  user_id INTEGER REFERENCES users (id) ON DELETE SET NULL,
  body TEXT NOT NULL,
  created_at INTEGER NOT NULL
);
CREATE INDEX thread_notes_thread ON thread_notes (thread_id, created_at);

CREATE TABLE filters (
  id INTEGER PRIMARY KEY,
  mailbox_id INTEGER NOT NULL REFERENCES mailboxes (id) ON DELETE CASCADE,
  name TEXT NOT NULL DEFAULT '',
  conditions TEXT NOT NULL,       -- JSON
  actions TEXT NOT NULL,          -- JSON
  position INTEGER NOT NULL DEFAULT 0,
  enabled INTEGER NOT NULL DEFAULT 1,
  created_at INTEGER NOT NULL
);
CREATE INDEX filters_mailbox ON filters (mailbox_id, position);

CREATE TABLE contacts (
  mailbox_id INTEGER NOT NULL REFERENCES mailboxes (id) ON DELETE CASCADE,
  address TEXT NOT NULL COLLATE NOCASE,
  name TEXT NOT NULL DEFAULT '',
  use_count INTEGER NOT NULL DEFAULT 1,
  last_used_at INTEGER NOT NULL,
  PRIMARY KEY (mailbox_id, address)
);

CREATE TABLE blocked_senders (
  id INTEGER PRIMARY KEY,
  mailbox_id INTEGER REFERENCES mailboxes (id) ON DELETE CASCADE,  -- NULL blocks for every mailbox
  pattern TEXT NOT NULL COLLATE NOCASE,     -- an address, or @domain
  created_at INTEGER NOT NULL
);
CREATE INDEX blocked_senders_pattern ON blocked_senders (pattern);

CREATE TABLE trusted_senders (    -- remote images always load for these
  user_id INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  pattern TEXT NOT NULL COLLATE NOCASE,
  PRIMARY KEY (user_id, pattern)
);

CREATE TABLE autoreply_log (
  mailbox_id INTEGER NOT NULL REFERENCES mailboxes (id) ON DELETE CASCADE,
  sender TEXT NOT NULL COLLATE NOCASE,
  sent_at INTEGER NOT NULL,
  PRIMARY KEY (mailbox_id, sender)
);

CREATE TABLE forward_destinations (
  address TEXT PRIMARY KEY COLLATE NOCASE,
  cf_id TEXT,
  verified_at INTEGER,
  created_at INTEGER NOT NULL
);

CREATE TABLE uploads (
  id TEXT PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  storage_key TEXT NOT NULL,
  filename TEXT NOT NULL,
  content_type TEXT NOT NULL,
  size INTEGER NOT NULL,
  created_at INTEGER NOT NULL
);

-- Operations ---------------------------------------------------------------------------------------

CREATE TABLE inbound_log (
  id INTEGER PRIMARY KEY,
  received_at INTEGER NOT NULL,
  mail_from TEXT NOT NULL DEFAULT '',
  rcpt_to TEXT NOT NULL DEFAULT '',
  subject TEXT NOT NULL DEFAULT '',
  size INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL CHECK (status IN ('delivered', 'spam', 'duplicate', 'rejected', 'unparsed', 'error')),
  reason TEXT,
  message_id INTEGER
);
CREATE INDEX inbound_log_time ON inbound_log (received_at DESC);

CREATE TABLE audit_log (
  id INTEGER PRIMARY KEY,
  user_id INTEGER REFERENCES users (id) ON DELETE SET NULL,
  action TEXT NOT NULL,
  target TEXT,
  details TEXT,
  ip TEXT,
  created_at INTEGER NOT NULL
);
CREATE INDEX audit_log_time ON audit_log (created_at DESC);

-- Per-day counters so the dashboard never scans messages. mailbox_id 0 holds mail rejected
-- before it reached a mailbox.
CREATE TABLE daily_stats (
  day TEXT NOT NULL,
  mailbox_id INTEGER NOT NULL,
  received INTEGER NOT NULL DEFAULT 0,
  sent INTEGER NOT NULL DEFAULT 0,
  spam INTEGER NOT NULL DEFAULT 0,
  rejected INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (day, mailbox_id)
);

CREATE TABLE counters (
  key TEXT PRIMARY KEY,
  value INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE cache (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  expires_at INTEGER NOT NULL
);
